namespace ghidra.examples;





using docking;
using docking;
using docking.action;
using docking.action;
using generic.theme;
using ghidra.framework.plugintool;
using ghidra.framework.plugintool;
using ghidra.program.model.listing;
using ghidra.program.util;

public class ShowInfoComponentProvider : ComponentProviderAdapter {
	private static Icon CLEAR_ICON = new GIcon("icon.sample.hello.world.action.clear");
	private static Icon PROVIDER_ICON = new GIcon("icon.sample.provider.hello.world");

	private JPanel panel;
	private JTextArea textArea;
	private DockingAction clearAction;
	private Program currentProgram;
	private ProgramLocation currentLocation;

	public ShowInfoComponentProvider(PluginTool tool, string owner) : base(tool, "Show Location Info", owner)
    {
		create();
		setIcon(PROVIDER_ICON);
		setDefaultWindowPosition(WindowPosition.BOTTOM);
		setTitle("Show Info");
		setVisible(true);
		createActions();
	}

	/* @Override */
	public JComponent getComponent() {
		return panel;
	}

	void clear() {
		currentProgram = null;
		currentLocation = null;
		textArea.setText("");
	}

	void locationChanged(Program program, ProgramLocation location) {
		this.currentProgram = program;
		this.currentLocation = location;
		if (isVisible()) {
			updateInfo();
		}
	}

	private void updateInfo() {
		if (currentLocation == null || currentLocation.getAddress() == null) {
			return;
		}

		CodeUnit cu =
			currentProgram.getListing().getCodeUnitContaining(currentLocation.getAddress());

		// TODO -- create the string to set

		string preview = CodeUnitFormat.DEFAULT.getRepresentationString(cu, true);
		if (cu is Instruction) {
			textArea.setText("Instruction: " + preview);
		}
		else {
			Data data = (Data) cu;
			if (data.isDefined()) {
				textArea.setText("Defined Data: " + preview);
			}
			else {
				textArea.setText("Undefined Data: " + preview);
			}
		}
	}

	private void create() {
		panel = new JPanel(new BorderLayout());
		textArea = new JTextArea(5, 25);
		textArea.setEditable(false);
		JScrollPane sp = new JScrollPane(textArea);
		panel.add(sp);
	}

	private void createActions() {
		clearAction = new DockingAction("Clear Text Area", getOwner()) {
			/* @Override */
			public void actionPerformed(ActionContext context) {
				textArea.setText("");
			}
		};
		clearAction.setToolBarData(new ToolBarData(CLEAR_ICON, null));

		clearAction.setEnabled(true);
		tool.addLocalAction(this, clearAction);
	}

	/* @Override */
	public void componentShown() {
		updateInfo();
	}

}
